function canWin(currentState) {
  const n = currentState.length;
  const grundy = new Array(n + 1).fill(0);

  for (let size = 2; size <= n; size++) {
    const reachable = new Set();
    for (let left = 0; left + 2 <= size; left++) {
      const right = size - 2 - left;
      reachable.add(grundy[left] ^ grundy[right]);
    }
    let mex = 0;
    while (reachable.has(mex)) {
      mex++;
    }
    grundy[size] = mex;
  }

  let total = 0;
  let run = 0;
  for (const ch of currentState) {
    if (ch === '+') {
      run++;
    } else {
      total ^= grundy[run];
      run = 0;
    }
  }
  total ^= grundy[run];
  return total !== 0;
}

