function canWin(currentState) {
  // Plain minimax with memo: a position wins if some flip leaves the opponent a losing position.
  // A position is stored as its sorted lengths of '+' runs (runs shorter than 2 allow no move).
  const memo = new Map();
  const wins = (runs) => {
    const key = runs.join(',');
    if (memo.has(key)) return memo.get(key);
    let result = false;
    for (let r = 0; r < runs.length && !result; r++) {
      for (let i = 0; i + 2 <= runs[r] && !result; i++) {
        const next = [...runs.slice(0, r), ...runs.slice(r + 1), i, runs[r] - 2 - i].filter(x => x >= 2).sort((a, b) => a - b);
        if (!wins(next)) result = true;
      }
    }
    memo.set(key, result);
    return result;
  };
  return wins(currentState.split('-').map(s => s.length).filter(x => x >= 2).sort((a, b) => a - b));
}

