function generate(rand, size) {
  const length = size === 'large' ? 60 : 1 + Math.floor(rand() * 12);
  const plus = size === 'large' ? 0.85 : 0.5 + rand() * 0.5;
  let state = '';
  for (let i = 0; i < length; i++) state += rand() < plus ? '+' : '-';
  return [state];
}
